import { useRef } from 'react';

import { useOverlaysEvents } from '../../../../core/hooks/useOverlaysEvents.js';
import { MouseCoordinate } from '../../../../core/types/overlays.js';
import { useOverlaysState } from '../../../hooks/store/selectors.js';

export function usePinnedAwarePosition() {
  const { mousePosition } = useOverlaysEvents();
  const { pinnedTooltip } = useOverlaysState();
  const ref = useRef<MouseCoordinate>();

  if (!pinnedTooltip) {
    ref.current = mousePosition;
  }

  return ref.current;
}
